import "./App.css";
import logo from "./images/jb_logo.png";
import Menu from "./components/Menu";
import { Grid } from "@mui/material";

function App() {
  return (
    <div className="App">
      <Grid
        container
        spacing={2}
        style={{ backgroundColor: "#000", color: "#fff", fontSize: "1.5vh" }}
      >
        <Grid
          size={4}
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <a
            href="https://maps.app.goo.gl/gJJ9bv1stsnmyG9D8"
            target="_blank"
            style={{ color: "#fff", textDecoration: "none" }}
          >
            716 E. 31st St La Grange Park, IL 60526
          </a>
        </Grid>
        <Grid size={4}>
          <img src={logo} width="100vh" />
        </Grid>
        <Grid
          size={4}
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          <a
            href="tel:+17088527494"
            target="_blank"
            style={{ color: "#fff", textDecoration: "none" }}
          >
            (708) 852-7494
          </a>
        </Grid>
      </Grid>

      <Menu />
      <div style={{ backgroundColor: "red", height: "50vh" }}>Test 6</div>
    </div>
  );
}

export default App;
